<?php /** @var \Illuminate\Database\Eloquent\Collection $products */ /** @var \Illuminate\Database\Eloquent\Collection $businesses */ ?>
<header class="page-head"><div><span class="eyebrow">INVENTARIO</span><h1>Productos</h1><p>Precios y existencias por local.</p></div><button class="btn btn-primary" onclick="document.querySelector('#new').showModal()">+ Añadir producto</button></header>
<div class="grid grid-3" style="max-width:820px;margin:0 0 20px"><div class="field"><label for="product-search">Buscar productos</label><input id="product-search" type="search" placeholder="Nombre o categoría"></div><div class="field"><label for="product-category-filter">Categoría</label><select id="product-category-filter"><option value="">Todas las categorías</option><option value="phone">Teléfonos</option><option value="accessory">Accesorios</option></select></div><div class="field"><label for="product-stock-filter">Disponibilidad</label><select id="product-stock-filter"><option value="">Todo el inventario</option><option value="available">Con existencias</option><option value="out-of-stock">Sin existencias</option></select></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const search=document.querySelector('#product-search'),category=document.querySelector('#product-category-filter'),stock=document.querySelector('#product-stock-filter'),applyFilters=()=>document.querySelectorAll('.data-table tbody tr').forEach(row=>{const matchesSearch=row.textContent.toLowerCase().includes(search.value.toLowerCase()),matchesCategory=!category.value||row.dataset.category===category.value,matchesStock=!stock.value||(stock.value==='available'?Number(row.dataset.stock)>0:Number(row.dataset.stock)===0);row.hidden=!(matchesSearch&&matchesCategory&&matchesStock)});[search,category,stock].forEach(filter=>filter.addEventListener('input',applyFilters))})</script>
<dialog class="card" id="new" style="border:0;padding:0;width:min(760px,90vw)"><form class="panel stack" method="post" action="./productos"><h2>Añadir producto</h2><div class="grid grid-3"><div class="field"><label>Nombre</label><input name="name" required placeholder="Nombre del producto"></div><div class="field"><label>Categoría</label><select name="category" required><option value="phone">Teléfono</option><option value="accessory">Accesorio</option></select></div><div class="field"><label>Precio USD</label><input name="price" type="number" min="0" required placeholder="0"></div></div><div class="grid grid-3"><?php foreach($businesses as $businessItem): ?><div class="field"><label>Stock · <?= htmlspecialchars($businessItem->name) ?></label><input name="stocks[<?= $businessItem->id ?>]" type="number" min="0" required value="0"></div><?php endforeach ?></div><div class="actions"><button class="btn btn-primary">Guardar producto</button><button type="button" class="btn btn-secondary" onclick="this.closest('dialog').close()">Cancelar</button></div></form></dialog>
<section class="card table-wrap"><div class="toolbar"><h2><?= $products->count() ?> productos</h2></div><table class="data-table"><thead><tr><th>Imagen</th><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock total</th><th></th></tr></thead><tbody><?php foreach($products as $product): $stock=$product->getStock(); ?><tr data-category="<?= $product->category ?>" data-stock="<?= $stock ?>"><td><img src="./resources/views/assets/product-placeholder.svg" alt="" width="44" height="44" style="display:block;border:1px solid #e0e7ff;border-radius:10px;background:#eef2ff"></td><td><strong><?= htmlspecialchars($product->name) ?></strong></td><td><span class="status status-warning"><?= $product->category === 'phone' ? 'Teléfono' : 'Accesorio' ?></span></td><td>$<?= $product->price ?></td><td><?= $stock ?> unidades</td><td class="actions"><button class="btn btn-secondary btn-sm" onclick="document.querySelector('#edit-<?= $product->id ?>').showModal()">Editar</button><a class="btn btn-danger btn-sm" href="./productos/<?= $product->id ?>/eliminar">Eliminar</a></td></tr><?php endforeach ?></tbody></table></section>
<?php foreach($products as $product): ?><dialog id="edit-<?= $product->id ?>" class="card" style="border:0;padding:0;width:min(700px,90vw)"><form method="post" action="./productos/<?= $product->id ?>" class="panel stack"><h2>Editar producto</h2><div class="grid grid-3"><div class="field"><label>Nombre</label><input name="name" value="<?= htmlspecialchars($product->name) ?>" required></div><div class="field"><label>Categoría</label><select name="category"><option value="phone" <?= $product->category==='phone'?'selected':'' ?>>Teléfono</option><option value="accessory" <?= $product->category==='accessory'?'selected':'' ?>>Accesorio</option></select></div><div class="field"><label>Precio USD</label><input name="price" type="number" min="0" value="<?= $product->price ?>" required></div></div><div class="grid grid-3"><?php foreach($businesses as $businessItem): $batch=$product->batches->first(fn($b)=>$b->business_id===$businessItem->id); ?><div class="field"><label>Stock · <?= htmlspecialchars($businessItem->name) ?></label><input name="stocks[<?= $businessItem->id ?>]" type="number" min="0" value="<?= $batch?->stock ?? 0 ?>" required></div><?php endforeach ?></div><div class="actions"><button class="btn btn-primary">Guardar</button><button type="button" class="btn btn-secondary" onclick="this.closest('dialog').close()">Cancelar</button></div></form></dialog><?php endforeach ?>
